const fs = require('fs');

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
let ptr = 0;

const n = parseInt(input[ptr++]);
const m = parseInt(input[ptr++]);

const st = new Array(n);
for (let i = 0; i < n; i++) {
    st[i] = parseInt(input[ptr++]);
}

const adj = Array.from({ length: n }, () => []);
const adjr = Array.from({ length: n }, () => []);

for (let i = 0; i < m; i++) {
    const u = parseInt(input[ptr++]) - 1;
    const v = parseInt(input[ptr++]) - 1;
    adj[u].push(v);
    adjr[v].push(u);
}

const mark = new Array(n).fill(0);
const ans = new Array(n).fill(0);

// DFS 1: Forward from type 1
for (let i = 0; i < n; i++) {
    if (!mark[i] && st[i] === 1) {
        const stack = [i];
        while (stack.length > 0) {
            const x = stack.pop();
            if (mark[x]) continue;
            mark[x] = 1;
            ans[x]++;
            for (const u of adj[x]) {
                if (!mark[u]) stack.push(u);
            }
        }
    }
}

// Reset marks
mark.fill(0);

// DFS 2: Backward from type 2
for (let i = 0; i < n; i++) {
    if (!mark[i] && st[i] === 2) {
        const stack = [i];
        while (stack.length > 0) {
            const x = stack.pop();
            if (mark[x]) continue;
            mark[x] = 1;
            ans[x]++;
            if (st[x] === 1) continue;
            for (const u of adjr[x]) {
                if (!mark[u]) stack.push(u);
            }
        }
    }
}

const output = [];
for (let i = 0; i < n; i++) {
    output.push(ans[i] === 2 ? '1' : '0');
}

console.log(output.join('\n'));

