    const adjr = new Array(n).fill(0).map(() => []);

    for (let i = 0; i < m; i++) {
        const u = parseInt(input[ptr++]) - 1;
        const v = parseInt(input[ptr++]) - 1;
        adj[u].push(v);
        adjr[v].push(u);
    }

    const mark = new Array(n).fill(0);
    const ans = new Array(n).fill(0);

    // Iterative DFS1
    for (let i = 0; i < n; i++) {
        if (!mark[i] && st[i] === 1) {
            const stack = [i];
