                for (const u of adj[x]) {
                    if (!mark[u]) {
                        stack.push(u);
                    }
                }
            }
        }
    }

    // Reset mark
    for (let i = 0; i < n; i++) mark[i] = 0;

    // Iterative DFS2
    for (let i = 0; i < n; i++) {
        if (!mark[i] && st[i] === 2) {
            const stack = [i];
            while (stack.length > 0) {
                const x = stack.pop();
                if (mark[x]) continue;
